void CommandStatusOperation::show() const
{
	const bool isTracing( Debug::isTracing( "CommandOperation" ) );

	if ( !isTracing )
		return;

	CommandOperation::show();

	cout << "Command Status Operation: " << endl;
	cout << "Bit Operation: ";

	if (bitOperation == SetBits)
	{
		cout << "SetBits" << endl;
	}
	else if (bitOperation == ClearBits)
	{
		cout << "ClearBits" << endl;
	}
	else
	{
		cout << "Unknown Bit Operation: " << (UINT16) bitOperation << endl;
	}

	cout << "Bits Masked: ";

	if (bits == 0)
	{
		cout << "None" << endl;
	}
	else
	{
		if ((bits & MediaJammedBit) == MediaJammedBit)
		{
			cout << "MediaJammedBit ";
		}
		
		if ((bits & LabelMissingBit) == LabelMissingBit)
		{
			cout << "LabelMissingBit ";
		}
		
		if ((bits & OutOfBoundsBit) == OutOfBoundsBit)
		{
			cout << "OutOfBoundsBit ";
		}
		
		if ((bits & TakingBit) == TakingBit)
		{
			cout << "TakingBit ";
		}

		cout << endl;
	}
}

